  Press(LobbyAction.Gift);yield return null;Press(LobbyAction.ClaimGift);Verify(Profile.crystals==100&&Profile.resonance==1,"Gift currency not awarded");Click(LobbyAction.ClaimGift);Verify(Profile.crystals==100&&Profile.resonance==1,"Daily reward was granted twice");yield return Shot("lobby-daily-reward");ClosePopup();
