  Press(LobbyAction.Settings);yield return null;var sliders=popupRoot.GetComponentsInChildren<Slider>();Verify(sliders.Length==2,"Missing audio sliders");sliders[0].value=.23f;sliders[1].value=.12f;Canvas.ForceUpdateCanvases();foreach(var slider in sliders){Verify(slider.fillRect.rect.width<=360.1f&&slider.fillRect.rect.height<=6.1f&&slider.handleRect.rect.height<=25.1f,"Audio slider overflows its track");}Verify(Mathf.Abs(Profile.music-.23f)<.001f&&Mathf.Abs(Profile.sound-.12f)<.001f&&Mathf.Abs(ambience.volume-.23f)<.001f,"Settings sliders are disconnected");Press(LobbyAction.ToggleJumpSound);yield return null;Verify(!Profile.jumpSound&&Mathf.Abs(Profile.sound-.12f)<.001f&&Mathf.Abs(Profile.music-.23f)<.001f,"Jump mute altered other audio settings");Press(LobbyAction.ToggleJumpSound);Verify(Profile.jumpSound,"Jump sound cannot be re-enabled");Press(LobbyAction.ToggleMotion);yield return null;Verify(Profile.reducedMotion&&stage.reducedMotion,"Reduced-motion setting not applied");yield return Shot("lobby-settings");Press(LobbyAction.ToggleMotion);ClosePopup();
  Profile.wins=1;Profile.claimedTasks=0;int before=Profile.crystals;Press(LobbyAction.Tasks);yield return null;Press(LobbyAction.ClaimTask,0);Verify(Profile.crystals==before+50,"Task reward failed");Click(LobbyAction.ClaimTask,0);Verify(Profile.crystals==before+50,"Task reward duplicated");ClosePopup();completed=1;Profile.claimedAchievements=0;before=Profile.crystals;ShowPage("Достижения");yield return null;Press(LobbyAction.ClaimAchievement,0);Verify(Profile.crystals==before+100,"Achievement reward failed");Click(LobbyAction.ClaimAchievement,0);Verify(Profile.crystals==before+100,"Achievement reward duplicated");ClosePopup();
  game.VerificationUnlock(3);Click(LobbyAction.Levels);yield return null;VerifyPageRays();Verify(!popupRoot.GetComponentsInChildren<LobbyButton>().First(b=>b.action==LobbyAction.SelectLevel&&b.value==3).GetComponent<Button>().interactable,"Locked level is interactable");Click(LobbyAction.SelectLevel,5);Verify(IsOpen&&Page=="Уровни","Locked level was entered");yield return Shot("lobby-levels");Press(LobbyAction.NextPage);Verify(levelPage==1,"Level pagination forward failed");Press(LobbyAction.PreviousPage);Verify(levelPage==0,"Level pagination backward failed");ClosePopup();game.VerificationUnlock(100);
  Press(LobbyAction.Play);yield return null;Verify(!IsOpen&&game.gameCamera.enabled&&game.CurrentLevel.id==100,"Play did not start unlocked campaign level");VerifyExclusiveScreen(false);game.RequestUI(CampaignUICommand.Home);yield return null;Verify(IsOpen,"In-game Home button did not return to lobby");VerifyExclusiveScreen(true);
  Press(LobbyAction.Events);yield return null;Press(LobbyAction.StartChallenge);yield return null;Verify(Mode==LobbyMode.Challenge&&!IsOpen&&ModeTarget==game.CurrentLevel.optimalTurns+2,"Challenge did not load its real level and turn objective");yield return game.PlayWitnessForLobbyTest();Verify(game.Victorious,"Challenge is not playable to victory");int challengeCrystals=Profile.crystals,challengeResonance=Profile.resonance;RecordVictory(game.CurrentLevel.id,game.Turns,3);Verify(Profile.crystals==challengeCrystals&&Profile.resonance==challengeResonance,"Daily challenge awarded a duplicate reward");modeWins++;game.RequestUI(CampaignUICommand.Primary);yield return null;Verify(IsOpen,"Challenge completion did not return home");
